-- =====================================================================================
-- BASE DE DATOS OEE / PAROS DE PRODUCCIÓN (PostgreSQL 14+) — esquema + datos cargados
-- Origen: SEGUIMIENTO_TEMPERAS_Y_VINILOS (2022-01-01 → 2025-03-28), procesado con etl_paros.py
-- Uso:  createdb oee && psql -d oee -v ON_ERROR_STOP=1 -f base_datos_oee_postgres.sql
-- Los datos se cargan ANTES de crear los triggers (los totales ya vienen calculados).
-- =====================================================================================

-- =====================================================================================
-- 01_ddl.sql  |  Esquema relacional OEE / paros de producción (PostgreSQL 14+)
-- Ejecutar con un usuario propietario:  psql -d oee -v ON_ERROR_STOP=1 -f 01_ddl.sql
-- Idempotente: usa IF NOT EXISTS donde es posible.
-- =====================================================================================
CREATE EXTENSION IF NOT EXISTS btree_gist;     -- necesaria para la restricción de no solapamiento

CREATE SCHEMA IF NOT EXISTS oee;     -- modelo analítico (dimensiones + hechos)
CREATE SCHEMA IF NOT EXISTS stg;     -- zona de aterrizaje del ETL
CREATE SCHEMA IF NOT EXISTS etl;     -- control de lotes, rechazos, funciones del pipeline
CREATE SCHEMA IF NOT EXISTS audit;   -- bitácora de cambios

-- ------------------------------------------------------------------ DIMENSIONES / MAESTROS
CREATE TABLE IF NOT EXISTS oee.dim_maquina (
    maquina_id  smallint PRIMARY KEY,
    nombre      text     NOT NULL UNIQUE,
    linea       text     NOT NULL DEFAULT 'Vinilos y témperas',
    activa      boolean  NOT NULL DEFAULT true
);

CREATE TABLE IF NOT EXISTS oee.dim_turno (
    turno_id         smallint PRIMARY KEY,                 -- 0 = sin dato
    nombre           text     NOT NULL UNIQUE,
    hora_inicio      time,
    hora_fin         time,
    horas_nominales  numeric(4,1)
);

CREATE TABLE IF NOT EXISTS oee.dim_operario (
    operario_id  integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,   -- 0 = sin dato
    nombre       text    NOT NULL UNIQUE,
    activo       boolean NOT NULL DEFAULT true
);

CREATE TABLE IF NOT EXISTS oee.dim_referencia (
    referencia_id  integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, -- 0 = sin dato
    nombre         text    NOT NULL UNIQUE,
    marca          text,
    volumen_cc     smallint,
    num_colores    smallint
);

CREATE TABLE IF NOT EXISTS oee.dim_area_impacto (
    area_id  smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre   text NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS oee.dim_motivo_paro (
    motivo_id      smallint PRIMARY KEY CHECK (motivo_id BETWEEN 1 AND 18),   -- = código del P-MTO-22
    nombre         text     NOT NULL,
    area_id        smallint NOT NULL REFERENCES oee.dim_area_impacto,
    es_planificado boolean  NOT NULL,       -- true: sale del tiempo planificado (no resta Disponibilidad)
    categoria_oee  text     NOT NULL CHECK (categoria_oee IN
        ('AVERIA','AJUSTE','CAMBIO_REFERENCIA','ESPERA','ABASTECIMIENTO','CALIDAD','ORGANIZACIONAL','PLANIFICADO'))
);

CREATE TABLE IF NOT EXISTS oee.dim_subcodigo_paro (
    subcodigo_id  integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    motivo_id     smallint NOT NULL REFERENCES oee.dim_motivo_paro,
    clave         text     NOT NULL,                -- '1.2.C', '5.11' ...
    nombre        text     NOT NULL,
    nivel         smallint NOT NULL,                -- 1 = sistema, 2 = componente
    clave_padre   text,
    UNIQUE (motivo_id, clave)
);

-- Catálogo del campo histórico "Tipo de paro" (horas de turno no trabajadas)
CREATE TABLE IF NOT EXISTS oee.dim_tipo_paro_maquina (
    tipo_paro_id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre                text    NOT NULL UNIQUE,
    pierde_disponibilidad boolean NOT NULL   -- false = sin demanda/programación (fuera del OEE, entra al TEEP)
);

-- Meta de producción (pacas/hora). referencia_id = 0 => meta por defecto de la máquina.
CREATE TABLE IF NOT EXISTS oee.meta_produccion (
    maquina_id      smallint NOT NULL REFERENCES oee.dim_maquina,
    referencia_id   integer  NOT NULL REFERENCES oee.dim_referencia,
    meta_pacas_hora numeric(8,2) NOT NULL CHECK (meta_pacas_hora > 0),
    origen          text NOT NULL DEFAULT 'ESTIMADA_P90' CHECK (origen IN ('OFICIAL','ESTIMADA_P90')),
    actualizado_en  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (maquina_id, referencia_id)
);

CREATE TABLE IF NOT EXISTS oee.dim_fecha (
    fecha          date PRIMARY KEY,
    anio           smallint NOT NULL,
    trimestre      smallint NOT NULL,
    mes            smallint NOT NULL,
    nombre_mes     text     NOT NULL,
    semana_iso     smallint NOT NULL,
    dia_semana     smallint NOT NULL,           -- 1 = lunes
    es_fin_semana  boolean  NOT NULL
);

-- ------------------------------------------------------------------------- TABLA DE HECHOS
-- Grano: una fila del libro "Base De Datos" (hoja hora-a-hora consolidada por turno/operaria).
-- tipo_registro = COMPLEMENTO_PAROS cuando la fila solo aporta paros adicionales de un turno.
CREATE TABLE IF NOT EXISTS oee.registros_produccion (
    registro_id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    row_hash             char(40)    NOT NULL UNIQUE,            -- llave de idempotencia del ETL
    fecha                date        NOT NULL REFERENCES oee.dim_fecha,
    maquina_id           smallint    NOT NULL REFERENCES oee.dim_maquina,
    turno_id             smallint    NOT NULL DEFAULT 0 REFERENCES oee.dim_turno,
    operario_id          integer     NOT NULL DEFAULT 0 REFERENCES oee.dim_operario,
    referencia_id        integer     NOT NULL DEFAULT 0 REFERENCES oee.dim_referencia,
    tipo_registro        text        NOT NULL CHECK (tipo_registro IN ('PRODUCCION','COMPLEMENTO_PAROS')),
    pacas_producidas     numeric(10,2) CHECK (pacas_producidas >= 0),
    pacas_no_conformes   numeric(10,2) NOT NULL DEFAULT 0 CHECK (pacas_no_conformes >= 0),  -- ver nota calidad
    horas_programadas    numeric(5,2)  NOT NULL DEFAULT 0 CHECK (horas_programadas BETWEEN 0 AND 24),
    horas_no_programadas numeric(5,2)  NOT NULL DEFAULT 0 CHECK (horas_no_programadas BETWEEN 0 AND 24),
    tipo_paro_id         integer REFERENCES oee.dim_tipo_paro_maquina,
    observacion          text,
    observacion_paro     text,
    calidad_dato         text NOT NULL DEFAULT 'OK' CHECK (calidad_dato IN ('OK','REVISAR','POSIBLE_DUPLICADO')),
    -- cifras desnormalizadas por el trigger de detalle (consistencia de duraciones)
    paro_planificado_min   numeric(8,2) NOT NULL DEFAULT 0,
    paro_no_planificado_min numeric(8,2) NOT NULL DEFAULT 0,
    archivo_origen       text,
    fila_origen          integer,
    lote_id              bigint,
    creado_en            timestamptz NOT NULL DEFAULT now(),
    actualizado_en       timestamptz NOT NULL DEFAULT now(),
    CHECK (tipo_registro = 'COMPLEMENTO_PAROS' OR horas_programadas > 0 OR pacas_producidas > 0)
);
COMMENT ON COLUMN oee.registros_produccion.pacas_no_conformes IS
 'El libro de origen NO registra producto no conforme. Por defecto 0 => Calidad = 100%. '
 'Cuando Calidad entregue el dato (o se integre el HMI), se carga aquí y el OEE se ajusta solo.';

CREATE INDEX IF NOT EXISTS ix_reg_fecha_maq    ON oee.registros_produccion (fecha, maquina_id);
CREATE INDEX IF NOT EXISTS ix_reg_maq_ref      ON oee.registros_produccion (maquina_id, referencia_id);
CREATE INDEX IF NOT EXISTS ix_reg_operario     ON oee.registros_produccion (operario_id);
CREATE INDEX IF NOT EXISTS ix_reg_calidad      ON oee.registros_produccion (calidad_dato) WHERE calidad_dato <> 'OK';
CREATE INDEX IF NOT EXISTS ix_reg_fecha_brin   ON oee.registros_produccion USING brin (fecha);

-- Detalle granular: una fila por (registro, código de paro).
CREATE TABLE IF NOT EXISTS oee.detalle_paros_produccion (
    detalle_id           bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    registro_id          bigint   NOT NULL REFERENCES oee.registros_produccion ON DELETE CASCADE,
    maquina_id           smallint NOT NULL REFERENCES oee.dim_maquina,   -- lo completa el trigger
    motivo_id            smallint NOT NULL REFERENCES oee.dim_motivo_paro,
    subcodigo_id         integer  REFERENCES oee.dim_subcodigo_paro,
    minutos              numeric(8,2) NOT NULL CHECK (minutos > 0),
    area_involucrada     text CHECK (area_involucrada IN ('Operarios','Personal_de_mantenimiento')),
    personal_involucrado text,
    -- Opcionales: solo cuando existe marca de tiempo (HMI / formato hora-a-hora digitalizado)
    inicio               timestamptz,
    fin                  timestamptz,
    creado_en            timestamptz NOT NULL DEFAULT now(),
    CHECK ((inicio IS NULL) = (fin IS NULL)),
    CHECK (fin IS NULL OR fin > inicio),
    -- Regla: en una misma máquina no pueden solaparse dos paros con marca de tiempo
    EXCLUDE USING gist (maquina_id WITH =, tstzrange(inicio, fin, '[)') WITH &&) WHERE (inicio IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS ix_det_registro ON oee.detalle_paros_produccion (registro_id);
CREATE INDEX IF NOT EXISTS ix_det_motivo   ON oee.detalle_paros_produccion (motivo_id, subcodigo_id);

-- ---------------------------------------------------------------------------- STAGING (ETL)
CREATE TABLE IF NOT EXISTS etl.lotes (
    lote_id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    archivo          text NOT NULL,
    sha256           char(64),
    iniciado_en      timestamptz NOT NULL DEFAULT now(),
    finalizado_en    timestamptz,
    estado           text NOT NULL DEFAULT 'EN_CURSO' CHECK (estado IN ('EN_CURSO','OK','ERROR')),
    filas_leidas     integer,
    filas_insertadas integer,
    filas_actualizadas integer,
    filas_eliminadas integer,
    mensaje          text
);
CREATE UNIQUE INDEX IF NOT EXISTS ux_lotes_sha_ok ON etl.lotes (sha256) WHERE estado = 'OK';

CREATE TABLE IF NOT EXISTS etl.rechazos (
    rechazo_id   bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    lote_id      bigint REFERENCES etl.lotes ON DELETE CASCADE,
    fila_origen  integer,
    regla        text NOT NULL,
    severidad    text NOT NULL CHECK (severidad IN ('ERROR','WARNING')),
    detalle      text,
    creado_en    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS stg.registros (
    lote_id bigint NOT NULL, row_hash char(40) NOT NULL, fila_origen integer, archivo_origen text,
    fecha date, maquina text, turno text, operario text, referencia text,
    pacas numeric, horas_programadas numeric, horas_no_programadas numeric,
    tipo_paro_maquina text, pierde_disp_tpm boolean, observacion text, observacion_paro text,
    tipo_registro text, calidad_dato text,
    PRIMARY KEY (lote_id, row_hash)
);
CREATE TABLE IF NOT EXISTS stg.paros (
    lote_id bigint NOT NULL, row_hash char(40) NOT NULL, motivo_id smallint, minutos numeric,
    subcodigo text, area_involucrada text, personal_involucrado text
);
CREATE INDEX IF NOT EXISTS ix_stg_paros ON stg.paros (lote_id, row_hash);

-- ------------------------------------------------------------------------------ AUDITORÍA
CREATE TABLE IF NOT EXISTS audit.log_cambios (
    log_id     bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tabla      text        NOT NULL,
    pk         text        NOT NULL,
    operacion  text        NOT NULL CHECK (operacion IN ('INSERT','UPDATE','DELETE')),
    usuario    text        NOT NULL DEFAULT current_user,
    en         timestamptz NOT NULL DEFAULT now(),
    antes      jsonb,
    despues    jsonb
);
CREATE INDEX IF NOT EXISTS ix_audit_tabla_pk ON audit.log_cambios (tabla, pk, en DESC);

-- GENERADO por etl/generate_seed.py — no editar a mano (edite etl/reglas.py y regenere).
-- Idempotente: re-ejecutable sin duplicar.
BEGIN;

ON CONFLICT (maquina_id) DO NOTHING;

ON CONFLICT (turno_id) DO NOTHING;


ON CONFLICT (nombre) DO NOTHING;

SELECT v.id, v.nombre, a.area_id, v.plan, v.cat FROM (VALUES
  (1, 'Falla del sistema electromecánico y/o de control', 'Mantenimiento', false, 'AVERIA'),
  (2, 'Espera de soporte de mantenimiento', 'Mantenimiento', false, 'ESPERA'),
  (3, 'Novedad en los sistemas de potencia (aire, energía, vapor)', 'Mantenimiento', false, 'AVERIA'),
  (4, 'Mantenimiento preventivo', 'Mantenimiento', false, 'AVERIA'),
  (5, 'Ajuste operativo', 'Producción', false, 'AJUSTE'),
  (6, 'Limpieza por derrame operativo / tiempo sin reportar', 'Producción', false, 'AJUSTE'),
  (7, 'Alistamiento de máquina / cambio de referencia', 'Producción', false, 'CAMBIO_REFERENCIA'),
  (8, 'Capacitación / reunión', 'Producción', false, 'ORGANIZACIONAL'),
  (9, 'Falta de operario', 'Producción', false, 'ORGANIZACIONAL'),
  (10, 'Paro por ventaja / evacuación / calidad', 'Producción', false, 'AJUSTE'),
  (11, 'Reproceso', 'Producción', false, 'CALIDAD'),
  (12, 'Materia prima defectuosa', 'Calidad', false, 'CALIDAD'),
  (13, 'En espera por el aval del laboratorio de microbiología', 'Calidad', false, 'ESPERA'),
  (14, 'Falta de materia prima', 'Almacén de materias primas', false, 'ABASTECIMIENTO'),
  (15, 'Cambio de insumos (roscadores, o''ring, etiquetas)', 'Paro programado', true, 'PLANIFICADO'),
  (16, 'Alimentación y aseo de la zona de trabajo y la máquina', 'Paro programado', true, 'PLANIFICADO'),
  (17, 'Pausa activa', 'Paro programado', true, 'PLANIFICADO'),
  (18, 'Desinfección', 'Paro programado', true, 'PLANIFICADO')
) AS v(id, nombre, area, plan, cat) JOIN oee.dim_area_impacto a ON a.nombre = v.area
ON CONFLICT (motivo_id) DO NOTHING;

ON CONFLICT (motivo_id, clave) DO NOTHING;

ON CONFLICT (nombre) DO NOTHING;

-- Calendario 2020-2030 (nombres de mes en español; no depende de lc_time del servidor)
SELECT d::date, EXTRACT(year FROM d), EXTRACT(quarter FROM d), EXTRACT(month FROM d),
       (ARRAY['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'])[EXTRACT(month FROM d)::int],
       EXTRACT(week FROM d), EXTRACT(isodow FROM d), EXTRACT(isodow FROM d) >= 6
FROM generate_series('2020-01-01'::date, '2030-12-31'::date, interval '1 day') AS d
ON CONFLICT (fecha) DO NOTHING;

COMMIT;

BEGIN;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
SELECT setval(pg_get_serial_sequence('oee.dim_operario','operario_id'), (SELECT max(operario_id) FROM oee.dim_operario));
SELECT setval(pg_get_serial_sequence('oee.dim_referencia','referencia_id'), (SELECT max(referencia_id) FROM oee.dim_referencia));
ON CONFLICT DO NOTHING;
SELECT setval(pg_get_serial_sequence('oee.registros_produccion','registro_id'), (SELECT max(registro_id) FROM oee.registros_produccion));
COMMIT;

-- =====================================================================================
-- 03_logica_negocio.sql | Reglas de integridad, triggers, auditoría y procedimientos del ETL
-- Requiere 01_ddl.sql y 02_seed_catalogos.sql.   PostgreSQL 14+ (CREATE PROCEDURE).
-- =====================================================================================

-- ------------------------------------------------------------------ AUDITORÍA GENÉRICA
CREATE OR REPLACE FUNCTION audit.fn_log() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    v_pk text;
BEGIN
    v_pk := CASE WHEN TG_OP = 'DELETE' THEN to_jsonb(OLD) ->> TG_ARGV[0]
                 ELSE to_jsonb(NEW) ->> TG_ARGV[0] END;
    VALUES (TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME, v_pk, TG_OP,
            CASE WHEN TG_OP <> 'INSERT' THEN to_jsonb(OLD) END,
            CASE WHEN TG_OP <> 'DELETE' THEN to_jsonb(NEW) END);
    RETURN NULL;
END $$;

-- Hechos: solo se auditan cambios de negocio (UPDATE OF ... / DELETE). Los INSERT masivos del ETL
-- ya quedan trazados por etl.lotes (lote_id) y los recálculos internos de totales no disparan el trigger.
DROP TRIGGER IF EXISTS trg_audit_registros ON oee.registros_produccion;
CREATE TRIGGER trg_audit_registros
    AFTER UPDATE OF fecha, maquina_id, turno_id, operario_id, referencia_id, pacas_producidas,
                    pacas_no_conformes, horas_programadas, horas_no_programadas, tipo_registro
          OR DELETE
    ON oee.registros_produccion
    FOR EACH ROW EXECUTE FUNCTION audit.fn_log('registro_id');

DROP TRIGGER IF EXISTS trg_audit_detalle ON oee.detalle_paros_produccion;
CREATE TRIGGER trg_audit_detalle
    AFTER UPDATE OF motivo_id, subcodigo_id, minutos, inicio, fin OR DELETE
    ON oee.detalle_paros_produccion
    FOR EACH ROW EXECUTE FUNCTION audit.fn_log('detalle_id');

-- Maestros críticos: auditoría completa (cambiar es_planificado altera todo el OEE histórico)
DROP TRIGGER IF EXISTS trg_audit_motivo ON oee.dim_motivo_paro;
CREATE TRIGGER trg_audit_motivo AFTER INSERT OR UPDATE OR DELETE ON oee.dim_motivo_paro
    FOR EACH ROW EXECUTE FUNCTION audit.fn_log('motivo_id');
DROP TRIGGER IF EXISTS trg_audit_meta ON oee.meta_produccion;
CREATE TRIGGER trg_audit_meta AFTER INSERT OR UPDATE OR DELETE ON oee.meta_produccion
    FOR EACH ROW EXECUTE FUNCTION audit.fn_log('maquina_id');

-- ------------------------------------------------------------------ REGLAS: REGISTRO
CREATE OR REPLACE FUNCTION oee.fn_registro_validar() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.pacas_no_conformes > COALESCE(NEW.pacas_producidas, 0) THEN
        RAISE EXCEPTION 'Pacas no conformes (%) no puede superar las producidas (%)',
            NEW.pacas_no_conformes, COALESCE(NEW.pacas_producidas, 0)
            USING ERRCODE = 'check_violation';
    END IF;
    IF TG_OP = 'UPDATE' THEN
        NEW.actualizado_en := now();
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS trg_registro_validar ON oee.registros_produccion;
CREATE TRIGGER trg_registro_validar BEFORE INSERT OR UPDATE ON oee.registros_produccion
    FOR EACH ROW EXECUTE FUNCTION oee.fn_registro_validar();

-- ------------------------------------------------------------------ REGLAS: DETALLE DE PAROS
-- (a) BEFORE: hereda la máquina del registro y, si hay marcas de tiempo, impone minutos = fin - inicio.
--     El no solapamiento temporal por máquina lo garantiza la restricción EXCLUDE del DDL (SQLSTATE 23P01).
CREATE OR REPLACE FUNCTION oee.fn_detalle_before() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    SELECT maquina_id INTO NEW.maquina_id FROM oee.registros_produccion WHERE registro_id = NEW.registro_id;
    IF NEW.maquina_id IS NULL THEN
        RAISE EXCEPTION 'Registro % inexistente', NEW.registro_id USING ERRCODE = 'foreign_key_violation';
    END IF;
    IF NEW.inicio IS NOT NULL AND NEW.fin IS NOT NULL THEN
        IF NEW.fin <= NEW.inicio THEN
            RAISE EXCEPTION 'El paro termina (%) antes de empezar (%)', NEW.fin, NEW.inicio
                USING ERRCODE = 'check_violation';
        END IF;
        NEW.minutos := round(extract(epoch FROM (NEW.fin - NEW.inicio)) / 60.0, 2);
    END IF;
    IF NEW.subcodigo_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM oee.dim_subcodigo_paro s WHERE s.subcodigo_id = NEW.subcodigo_id AND s.motivo_id = NEW.motivo_id) THEN
        RAISE EXCEPTION 'El subcódigo % no pertenece al código de paro %', NEW.subcodigo_id, NEW.motivo_id
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS trg_detalle_before ON oee.detalle_paros_produccion;
CREATE TRIGGER trg_detalle_before BEFORE INSERT OR UPDATE ON oee.detalle_paros_produccion
    FOR EACH ROW EXECUTE FUNCTION oee.fn_detalle_before();

-- (b) AFTER: recalcula los totales del registro y marca 'REVISAR' si los paros exceden el tiempo
--     del turno (+5 min de tolerancia). No bloquea la carga histórica: la inconsistencia queda visible.
CREATE OR REPLACE FUNCTION oee.fn_detalle_after() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    v_id bigint := CASE WHEN TG_OP = 'DELETE' THEN OLD.registro_id ELSE NEW.registro_id END;
BEGIN
    UPDATE oee.registros_produccion r
       SET paro_planificado_min    = COALESCE(x.planificado, 0),
           paro_no_planificado_min = COALESCE(x.no_planificado, 0),
           calidad_dato = CASE
               WHEN r.calidad_dato = 'OK' AND r.horas_programadas > 0
                    AND COALESCE(x.planificado, 0) + COALESCE(x.no_planificado, 0) > r.horas_programadas * 60 + 5
               THEN 'REVISAR' ELSE r.calidad_dato END
      FROM (SELECT sum(d.minutos) FILTER (WHERE m.es_planificado)     AS planificado,
                   sum(d.minutos) FILTER (WHERE NOT m.es_planificado) AS no_planificado
              FROM oee.detalle_paros_produccion d
              JOIN oee.dim_motivo_paro m USING (motivo_id)
             WHERE d.registro_id = v_id) x
     WHERE r.registro_id = v_id;
    RETURN NULL;
END $$;

DROP TRIGGER IF EXISTS trg_detalle_after ON oee.detalle_paros_produccion;
CREATE TRIGGER trg_detalle_after AFTER INSERT OR UPDATE OF minutos, motivo_id OR DELETE
    ON oee.detalle_paros_produccion
    FOR EACH ROW EXECUTE FUNCTION oee.fn_detalle_after();

-- ------------------------------------------------------------------ API PARA HMI / CAPTURA DIRECTA
-- Registra un paro con marcas de tiempo y devuelve el id; ante solapamiento da un mensaje claro.
CREATE OR REPLACE FUNCTION oee.fn_registrar_paro(
    p_registro bigint, p_motivo smallint, p_inicio timestamptz, p_fin timestamptz,
    p_subcodigo text DEFAULT NULL, p_area text DEFAULT NULL, p_personal text DEFAULT NULL)
RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE
    v_sub integer; v_id bigint; v_maq smallint; v_choque record;
BEGIN
    SELECT maquina_id INTO v_maq FROM oee.registros_produccion WHERE registro_id = p_registro;
    IF v_maq IS NULL THEN RAISE EXCEPTION 'Registro % no existe', p_registro; END IF;
    SELECT d.detalle_id, d.inicio, d.fin INTO v_choque
      FROM oee.detalle_paros_produccion d
     WHERE d.maquina_id = v_maq AND d.inicio IS NOT NULL
       AND tstzrange(d.inicio, d.fin, '[)') && tstzrange(p_inicio, p_fin, '[)') LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'Solapamiento con el paro % (% → %) en la misma máquina',
            v_choque.detalle_id, v_choque.inicio, v_choque.fin USING ERRCODE = 'exclusion_violation';
    END IF;
    IF p_subcodigo IS NOT NULL THEN
        SELECT subcodigo_id INTO v_sub FROM oee.dim_subcodigo_paro WHERE motivo_id = p_motivo AND clave = p_subcodigo;
        IF v_sub IS NULL THEN RAISE EXCEPTION 'Subcódigo % no existe para el código %', p_subcodigo, p_motivo; END IF;
    END IF;
    VALUES (p_registro, p_motivo, v_sub, 1, p_inicio, p_fin, p_area, p_personal)   -- minutos lo recalcula el trigger
    RETURNING detalle_id INTO v_id;
    RETURN v_id;
END $$;

-- ------------------------------------------------------------------ FUNCIONES DEL PIPELINE ETL
-- Devuelve NULL si el mismo archivo (SHA-256) ya fue cargado con éxito => ejecución idempotente.
CREATE OR REPLACE FUNCTION etl.fn_iniciar_lote(p_archivo text, p_sha text, p_filas integer) RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE v_id bigint;
BEGIN
    IF EXISTS (SELECT 1 FROM etl.lotes WHERE sha256 = p_sha AND estado = 'OK') THEN
        RETURN NULL;
    END IF;
    RETURNING lote_id INTO v_id;
    RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION etl.fn_registrar_error(p_archivo text, p_mensaje text) RETURNS void
LANGUAGE sql AS $$
$$;

-- Meta estimada: no pisa metas OFICIALES. referencia NULL => meta por defecto de la máquina (id 0).
CREATE OR REPLACE FUNCTION etl.fn_upsert_meta_estimada(p_maquina text, p_referencia text, p_meta numeric) RETURNS void
LANGUAGE plpgsql AS $$
DECLARE v_maq smallint; v_ref integer;
BEGIN
    SELECT maquina_id INTO v_maq FROM oee.dim_maquina WHERE nombre = p_maquina;
    IF p_referencia IS NULL THEN v_ref := 0;
    ELSE SELECT referencia_id INTO v_ref FROM oee.dim_referencia WHERE nombre = p_referencia; END IF;
    IF v_maq IS NULL OR v_ref IS NULL OR p_meta IS NULL OR p_meta <= 0 THEN RETURN; END IF;
    VALUES (v_maq, v_ref, p_meta, 'ESTIMADA_P90')
    ON CONFLICT (maquina_id, referencia_id) DO UPDATE
        SET meta_pacas_hora = EXCLUDED.meta_pacas_hora, actualizado_en = now()
        WHERE oee.meta_produccion.origen <> 'OFICIAL';
END $$;

-- Promoción staging -> modelo (una sola transacción; el COMMIT lo hace quien llama).
CREATE OR REPLACE PROCEDURE etl.sp_promover_lote(p_lote bigint, p_reemplazar_desde date DEFAULT NULL)
LANGUAGE plpgsql AS $$
DECLARE
    v_ins integer := 0; v_upd integer := 0; v_del integer := 0; v_desconocidos integer;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM etl.lotes WHERE lote_id = p_lote AND estado = 'EN_CURSO') THEN
        RAISE EXCEPTION 'Lote % no existe o ya fue cerrado', p_lote;
    END IF;

    -- 1) Dimensiones dinámicas (operarios, referencias, tipos de paro de máquina)
    SELECT DISTINCT operario FROM stg.registros WHERE lote_id = p_lote AND operario IS NOT NULL
    ON CONFLICT (nombre) DO NOTHING;

    SELECT DISTINCT referencia,
           NULLIF(btrim(regexp_replace(referencia, '\s*\d+\s*cc.*$', '', 'i')), ''),
           substring(referencia FROM '(\d+)\s*[cC][cC]')::smallint,
           substring(referencia FROM '\((\d+)\s*col\)')::smallint
      FROM stg.registros WHERE lote_id = p_lote AND referencia IS NOT NULL
    ON CONFLICT (nombre) DO NOTHING;

    SELECT tipo_paro_maquina, bool_or(COALESCE(pierde_disp_tpm, true))
      FROM stg.registros WHERE lote_id = p_lote AND tipo_paro_maquina IS NOT NULL GROUP BY 1
    ON CONFLICT (nombre) DO NOTHING;

    -- 2) Turnos o máquinas fuera de catálogo: se avisa (no se pierde el dato: queda como 'Sin dato')
    SELECT count(*) INTO v_desconocidos FROM stg.registros s
     WHERE s.lote_id = p_lote AND s.turno IS NOT NULL AND NOT EXISTS (SELECT 1 FROM oee.dim_turno t WHERE t.nombre = s.turno);
    IF v_desconocidos > 0 THEN
        SELECT p_lote, s.fila_origen, 'R10_TURNO_NO_CATALOGADO', 'WARNING', 'turno=' || s.turno
          FROM stg.registros s
         WHERE s.lote_id = p_lote AND s.turno IS NOT NULL
           AND NOT EXISTS (SELECT 1 FROM oee.dim_turno t WHERE t.nombre = s.turno);
    END IF;

    -- 3) Ventana de re-sincronización: elimina lo que ya no existe en el archivo desde la fecha dada
    IF p_reemplazar_desde IS NOT NULL THEN
        DELETE FROM oee.registros_produccion r
         WHERE r.fecha >= p_reemplazar_desde
           AND r.archivo_origen IN (SELECT DISTINCT archivo_origen FROM stg.registros WHERE lote_id = p_lote)
           AND NOT EXISTS (SELECT 1 FROM stg.registros s WHERE s.lote_id = p_lote AND s.row_hash = r.row_hash);
        GET DIAGNOSTICS v_del = ROW_COUNT;
    END IF;

    -- 4) Upsert de hechos por hash de contenido (sin duplicados)
    WITH src AS (
        SELECT s.*, m.maquina_id, COALESCE(t.turno_id, 0) AS turno_id, COALESCE(o.operario_id, 0) AS operario_id,
               COALESCE(r.referencia_id, 0) AS referencia_id, tp.tipo_paro_id
          FROM stg.registros s
          JOIN oee.dim_maquina m ON m.nombre = s.maquina
          LEFT JOIN oee.dim_turno t ON t.nombre = s.turno
          LEFT JOIN oee.dim_operario o ON o.nombre = s.operario
          LEFT JOIN oee.dim_referencia r ON r.nombre = s.referencia
          LEFT JOIN oee.dim_tipo_paro_maquina tp ON tp.nombre = s.tipo_paro_maquina
         WHERE s.lote_id = p_lote
    ), up AS (
                pacas_producidas, horas_programadas, horas_no_programadas, tipo_paro_id,
                observacion, observacion_paro, calidad_dato, archivo_origen, fila_origen, lote_id)
        SELECT row_hash, fecha, maquina_id, turno_id, operario_id, referencia_id, tipo_registro,
               pacas, horas_programadas, horas_no_programadas, tipo_paro_id,
               observacion, observacion_paro, calidad_dato, archivo_origen, fila_origen, p_lote
          FROM src
        ON CONFLICT (row_hash) DO UPDATE
           SET observacion = EXCLUDED.observacion, observacion_paro = EXCLUDED.observacion_paro,
               fila_origen = EXCLUDED.fila_origen, lote_id = EXCLUDED.lote_id
         WHERE (t.observacion, t.observacion_paro, t.fila_origen) IS DISTINCT FROM
               (EXCLUDED.observacion, EXCLUDED.observacion_paro, EXCLUDED.fila_origen)
        RETURNING (xmax = 0) AS fue_insert
    )
    SELECT count(*) FILTER (WHERE fue_insert), count(*) FILTER (WHERE NOT fue_insert) INTO v_ins, v_upd FROM up;

    -- 5) Detalle de paros de los registros que aún no lo tienen (idempotente)
    SELECT r.registro_id, p.motivo_id, sc.subcodigo_id, p.minutos,
           CASE WHEN p.area_involucrada IN ('Operarios', 'Personal_de_mantenimiento') THEN p.area_involucrada END,
           p.personal_involucrado
      FROM stg.paros p
      JOIN oee.registros_produccion r ON r.row_hash = p.row_hash
      LEFT JOIN oee.dim_subcodigo_paro sc ON sc.motivo_id = p.motivo_id AND sc.clave = p.subcodigo
     WHERE p.lote_id = p_lote
       AND NOT EXISTS (SELECT 1 FROM oee.detalle_paros_produccion d WHERE d.registro_id = r.registro_id);

    -- 6) Cierre del lote y limpieza del staging
    DELETE FROM stg.paros WHERE lote_id = p_lote;
    DELETE FROM stg.registros WHERE lote_id = p_lote;
    UPDATE etl.lotes
       SET estado = 'OK', finalizado_en = now(), filas_insertadas = v_ins, filas_actualizadas = v_upd,
           filas_eliminadas = v_del,
           mensaje = format('insertadas=%s actualizadas=%s eliminadas=%s', v_ins, v_upd, v_del)
     WHERE lote_id = p_lote;
END $$;

-- =====================================================================================
-- 04_vistas_oee.sql | Capa semántica en PostgreSQL consumida por Grafana y Power BI
--
-- Definiciones (todas en minutos; ver docs/03_reglas_oee.md):
--   Tiempo programado   = horas_programadas × 60                (columna "Horas trabajadas" del libro)
--   Tiempo planificado  = programado − paros planificados       (códigos 15,16,17,18: es_planificado)
--   Tiempo operativo    = planificado − paros NO planificados   (códigos 1–14)
--   Disponibilidad (A)  = operativo / planificado
--   Rendimiento    (P)  = pacas producidas / (operativo/60 × meta pacas/hora)
--   Calidad        (Q)  = (pacas − no conformes) / pacas
--   OEE = A × P × Q  =  pacas buenas / (planificado/60 × meta)
--   Las "horas no trabajadas" (calendario fuera de programación) NO entran al OEE: alimentan la
--   utilización de calendario (TEEP) y su causa (Tipo de paro).
-- =====================================================================================

-- 1) Hechos a nivel de fila del libro, con alcance OEE y meta resuelta ----------------------
CREATE OR REPLACE VIEW oee.v_oee_hechos AS
WITH base AS (
    SELECT r.*,
           bool_or(r.tipo_registro = 'PRODUCCION')
               OVER (PARTITION BY r.fecha, r.maquina_id, r.turno_id, r.operario_id, r.referencia_id) AS grupo_con_produccion
      FROM oee.registros_produccion r
     WHERE r.calidad_dato <> 'POSIBLE_DUPLICADO'          -- las copias exactas no doblan la producción
)
SELECT b.registro_id, b.fecha, b.maquina_id, b.turno_id, b.operario_id, b.referencia_id,
       b.tipo_registro, b.calidad_dato,
       b.grupo_con_produccion                                   AS en_alcance_oee,
       COALESCE(m1.meta_pacas_hora, m0.meta_pacas_hora)         AS meta_pacas_hora,
       CASE WHEN m1.meta_pacas_hora IS NOT NULL THEN m1.origen ELSE m0.origen END AS origen_meta,
       b.horas_programadas * 60                                 AS min_programados,
       CASE WHEN b.grupo_con_produccion THEN b.paro_planificado_min    ELSE 0 END AS min_paro_planificado,
       CASE WHEN b.grupo_con_produccion THEN b.paro_no_planificado_min ELSE 0 END AS min_paro_no_planificado,
       COALESCE(b.pacas_producidas, 0)                          AS pacas_producidas,
       b.pacas_no_conformes,
       CASE WHEN b.tipo_registro = 'PRODUCCION' THEN b.horas_no_programadas ELSE 0 END AS horas_no_programadas,
       b.tipo_paro_id
  FROM base b
  LEFT JOIN oee.meta_produccion m1 ON m1.maquina_id = b.maquina_id AND m1.referencia_id = b.referencia_id
  LEFT JOIN oee.meta_produccion m0 ON m0.maquina_id = b.maquina_id AND m0.referencia_id = 0;

-- 2) Grano turno-operaria-referencia (une producción + sus paros complementarios) ----------
CREATE OR REPLACE VIEW oee.v_oee_turno AS
WITH g AS (
    SELECT fecha, maquina_id, turno_id, operario_id, referencia_id,
           max(meta_pacas_hora)                       AS meta_pacas_hora,
           sum(min_programados)                       AS min_programados,
           sum(min_paro_planificado)                  AS min_paro_planificado,
           sum(min_paro_no_planificado)               AS min_paro_no_planificado_bruto,
           sum(pacas_producidas)                      AS pacas_producidas,
           sum(pacas_no_conformes)                    AS pacas_no_conformes,
           sum(horas_no_programadas)                  AS horas_no_programadas,
           bool_or(calidad_dato = 'REVISAR')          AS requiere_revision
      FROM oee.v_oee_hechos
     WHERE en_alcance_oee
     GROUP BY fecha, maquina_id, turno_id, operario_id, referencia_id
), c AS (   -- recorta para que ningún componente de tiempo sea negativo (registros marcados REVISAR)
    SELECT g.*,
           GREATEST(min_programados - min_paro_planificado, 0)                         AS min_planificados,
           LEAST(min_paro_no_planificado_bruto, GREATEST(min_programados - min_paro_planificado, 0)) AS min_paro_no_planificado
      FROM g
)
SELECT c.fecha, c.maquina_id, c.turno_id, c.operario_id, c.referencia_id,
       c.min_programados, c.min_paro_planificado, c.min_planificados, c.min_paro_no_planificado,
       c.min_planificados - c.min_paro_no_planificado                                   AS min_operativos,
       c.pacas_producidas, c.pacas_no_conformes, c.pacas_producidas - c.pacas_no_conformes AS pacas_buenas,
       c.meta_pacas_hora,
       (c.min_planificados - c.min_paro_no_planificado) / 60.0 * c.meta_pacas_hora       AS pacas_ideales_operativas,
       c.min_planificados / 60.0 * c.meta_pacas_hora                                      AS pacas_ideales_planificadas,
       c.horas_no_programadas, c.requiere_revision,
       -- indicadores a este grano
       round((c.min_planificados - c.min_paro_no_planificado) / NULLIF(c.min_planificados, 0), 4) AS disponibilidad,
       round(c.pacas_producidas / NULLIF((c.min_planificados - c.min_paro_no_planificado) / 60.0 * c.meta_pacas_hora, 0), 4) AS rendimiento,
       round((c.pacas_producidas - c.pacas_no_conformes) / NULLIF(c.pacas_producidas, 0), 4)       AS calidad,
       round((c.pacas_producidas - c.pacas_no_conformes) / NULLIF(c.min_planificados / 60.0 * c.meta_pacas_hora, 0), 4) AS oee
  FROM c;

-- 3) Agregados (los ratios se recalculan desde sumas: nunca promedian porcentajes) -----------
CREATE OR REPLACE VIEW oee.v_oee_diario AS
SELECT t.fecha, m.nombre AS maquina, t.maquina_id,
       sum(min_programados) AS min_programados, sum(min_planificados) AS min_planificados,
       sum(min_paro_planificado) AS min_paro_planificado, sum(min_paro_no_planificado) AS min_paro_no_planificado,
       sum(min_operativos) AS min_operativos, sum(pacas_producidas) AS pacas_producidas,
       sum(pacas_buenas) AS pacas_buenas, sum(pacas_ideales_operativas) AS pacas_ideales_operativas,
       sum(pacas_ideales_planificadas) AS pacas_ideales_planificadas, sum(horas_no_programadas) AS horas_no_programadas,
       round(sum(min_operativos) / NULLIF(sum(min_planificados), 0), 4)                    AS disponibilidad,
       round(sum(pacas_producidas) / NULLIF(sum(pacas_ideales_operativas), 0), 4)           AS rendimiento,
       round(sum(pacas_buenas) / NULLIF(sum(pacas_producidas), 0), 4)                       AS calidad,
       round(sum(pacas_buenas) / NULLIF(sum(pacas_ideales_planificadas), 0), 4)             AS oee
  FROM oee.v_oee_turno t JOIN oee.dim_maquina m USING (maquina_id)
 GROUP BY t.fecha, m.nombre, t.maquina_id;

CREATE OR REPLACE VIEW oee.v_oee_mensual AS
SELECT date_trunc('month', fecha)::date AS mes, maquina, maquina_id,
       sum(min_planificados) AS min_planificados, sum(min_paro_no_planificado) AS min_paro_no_planificado,
       sum(min_operativos) AS min_operativos, sum(pacas_producidas) AS pacas_producidas, sum(pacas_buenas) AS pacas_buenas,
       round(sum(min_operativos) / NULLIF(sum(min_planificados), 0), 4)             AS disponibilidad,
       round(sum(pacas_producidas) / NULLIF(sum(pacas_ideales_operativas), 0), 4)    AS rendimiento,
       round(sum(pacas_buenas) / NULLIF(sum(pacas_producidas), 0), 4)                AS calidad,
       round(sum(pacas_buenas) / NULLIF(sum(pacas_ideales_planificadas), 0), 4)      AS oee
  FROM oee.v_oee_diario
 GROUP BY 1, maquina, maquina_id;

-- 4) Paros: todos los minutos registrados (incluye los de turnos sin fila de producción) -----
CREATE OR REPLACE VIEW oee.v_paros_detalle AS
SELECT d.detalle_id, r.fecha, r.maquina_id, ma.nombre AS maquina, r.turno_id, tu.nombre AS turno,
       r.operario_id, op.nombre AS operario, r.referencia_id, rf.nombre AS referencia,
       d.motivo_id, mo.nombre AS motivo, '[' || lpad(mo.motivo_id::text, 2, '0') || '] ' || mo.nombre AS motivo_etiqueta,
       ai.nombre AS area_impacto, mo.es_planificado, mo.categoria_oee,
       sc.clave AS subcodigo_clave, COALESCE(sc.nombre, 'Sin especificar') AS subcodigo,
       d.area_involucrada, d.personal_involucrado, d.minutos, d.minutos / 60.0 AS horas
  FROM oee.detalle_paros_produccion d
  JOIN oee.registros_produccion r ON r.registro_id = d.registro_id AND r.calidad_dato <> 'POSIBLE_DUPLICADO'
  JOIN oee.dim_maquina ma ON ma.maquina_id = r.maquina_id
  JOIN oee.dim_turno tu ON tu.turno_id = r.turno_id
  JOIN oee.dim_operario op ON op.operario_id = r.operario_id
  JOIN oee.dim_referencia rf ON rf.referencia_id = r.referencia_id
  JOIN oee.dim_motivo_paro mo ON mo.motivo_id = d.motivo_id
  JOIN oee.dim_area_impacto ai ON ai.area_id = mo.area_id
  LEFT JOIN oee.dim_subcodigo_paro sc ON sc.subcodigo_id = d.subcodigo_id;

-- Pareto con % y % acumulado, parametrizable (Grafana/Power BI/psql)
CREATE OR REPLACE FUNCTION oee.fn_pareto_paros(
    p_desde date, p_hasta date, p_maquina text DEFAULT NULL, p_solo_no_planificados boolean DEFAULT true)
RETURNS TABLE (posicion int, motivo text, horas numeric, pct numeric, pct_acumulado numeric, clase_abc text)
LANGUAGE sql STABLE AS $$
    WITH t AS (
        SELECT motivo_etiqueta AS motivo, sum(horas) AS horas
          FROM oee.v_paros_detalle
         WHERE fecha BETWEEN p_desde AND p_hasta
           AND (p_maquina IS NULL OR maquina = p_maquina)
           AND (NOT p_solo_no_planificados OR NOT es_planificado)
         GROUP BY 1
    ), p AS (
        SELECT motivo, horas, horas / NULLIF(sum(horas) OVER (), 0) AS pct,
               sum(horas) OVER (ORDER BY horas DESC, motivo) / NULLIF(sum(horas) OVER (), 0) AS acum
          FROM t
    )
    SELECT (row_number() OVER (ORDER BY horas DESC, motivo))::int, motivo, round(horas, 2), round(pct, 4), round(acum, 4),
           CASE WHEN acum - pct < 0.80 THEN 'A' WHEN acum - pct < 0.95 THEN 'B' ELSE 'C' END
      FROM p ORDER BY horas DESC, motivo;
$$;

-- 5) Utilización de calendario (TEEP) y causa de las horas fuera de programación -------------
CREATE OR REPLACE VIEW oee.v_horas_no_programadas AS
SELECT r.fecha, ma.nombre AS maquina, COALESCE(tp.nombre, 'Sin causa registrada') AS causa,
       COALESCE(tp.pierde_disponibilidad, false) AS causa_operativa,    -- true: insumos/personal/calidad; false: demanda o planeación
       sum(r.horas_no_programadas) AS horas_no_programadas, sum(r.horas_programadas) AS horas_programadas
  FROM oee.registros_produccion r
  JOIN oee.dim_maquina ma USING (maquina_id)
  LEFT JOIN oee.dim_tipo_paro_maquina tp USING (tipo_paro_id)
 WHERE r.tipo_registro = 'PRODUCCION' AND r.calidad_dato <> 'POSIBLE_DUPLICADO' AND r.horas_no_programadas > 0
 GROUP BY 1, 2, 3, 4;

-- 6) Calidad de datos: lo que el ETL cargó pero que conviene revisar -------------------------
CREATE OR REPLACE VIEW oee.v_calidad_datos AS
SELECT 'Registros marcados REVISAR (paros > turno)'          AS control, count(*)::bigint AS filas FROM oee.registros_produccion WHERE calidad_dato = 'REVISAR'
UNION ALL SELECT 'Posibles duplicados excluidos del OEE',       count(*) FROM oee.registros_produccion WHERE calidad_dato = 'POSIBLE_DUPLICADO'
UNION ALL SELECT 'Paros sin fila de producción (fuera del OEE, dentro del Pareto)', count(*) FROM oee.v_oee_hechos WHERE NOT en_alcance_oee
UNION ALL SELECT 'Registros de producción sin meta resuelta',   count(*) FROM oee.v_oee_hechos WHERE en_alcance_oee AND meta_pacas_hora IS NULL
UNION ALL SELECT 'Registros sin operaria / turno / referencia', count(*) FROM oee.registros_produccion WHERE operario_id = 0 OR turno_id = 0 OR referencia_id = 0
UNION ALL SELECT 'Subcódigo 1/3/5 sin especificar',             count(*) FROM oee.detalle_paros_produccion WHERE motivo_id IN (1, 3, 5) AND subcodigo_id IS NULL;

-- 7) Salud del pipeline (Grafana: panel de frescura / alerta de ETL caído) -------------------
CREATE OR REPLACE VIEW etl.v_estado_pipeline AS
SELECT (SELECT max(finalizado_en) FROM etl.lotes WHERE estado = 'OK')                               AS ultimo_lote_ok,
       EXTRACT(epoch FROM now() - (SELECT max(finalizado_en) FROM etl.lotes WHERE estado = 'OK')) / 3600.0 AS horas_desde_ultimo_ok,
       (SELECT count(*) FROM etl.lotes WHERE estado = 'ERROR' AND iniciado_en > now() - interval '24 hours') AS errores_24h,
       (SELECT max(fecha) FROM oee.registros_produccion)                                            AS ultima_fecha_dato;


-- Verificación rápida
SELECT 'registros' AS tabla, count(*) FROM oee.registros_produccion
UNION ALL SELECT 'detalle_paros', count(*) FROM oee.detalle_paros_produccion
UNION ALL SELECT 'rechazos', count(*) FROM etl.rechazos;
SELECT * FROM oee.v_oee_mensual ORDER BY mes, maquina LIMIT 12;